	(26, 1, '2024-05-22 07:37:38', '2024-05-22 07:37:38', '{\n    "sidebars_widgets[ear-content-2]": {\n        "value": [\n            "block-8"\n        ],\n        "type": "option",\n        "user_id": 1,\n        "date_modified_gmt": "2024-05-22 07:35:42"\n    },\n    "widget_block[8]": {\n        "value": {\n            "encoded_serialized_instance": "YToxOntzOjc6ImNvbnRlbnQiO3M6MTA3OiI8ZGl2IGlkPSJwc3QtY29udGFpbmVyIj4KCQkJCQkJPGRpdj5QaGlsaXBwaW5lIFN0YW5kYXJkIFRpbWU6PC9kaXY+PGRpdiBpZD0icHN0LXRpbWUiPjwvZGl2PgoJCQkJCSAgIDwvZGl2PiI7fQ==",\n            "title": "",\n            "is_widget_customizer_js_value": true,\n            "instance_hash_key": "590a4d7f2ced659244536db539ed002f",\n            "raw_instance": {\n                "content": "<div id=\\"pst-container\\">\\n\\t\\t\\t\\t\\t\\t<div>Philippine Standard Time:</div><div id=\\"pst-time\\"></div>\\n\\t\\t\\t\\t\\t   </div>"\n            }\n        },\n        "type": "option",\n        "user_id": 1,\n        "date_modified_gmt": "2024-05-22 07:37:38"\n    },\n    "blogdescription": {\n        "value": "One Crop at a Time",\n        "type": "option",\n        "user_id": 1,\n        "date_modified_gmt": "2024-05-22 07:37:38"\n    },\n    "gwt-wordpress-26.0.0::custom_logo": {\n        "value": 29,\n        "type": "theme_mod",\n        "user_id": 1,\n        "date_modified_gmt": "2024-05-22 07:37:38"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', '17581c33-1d72-4681-95d6-ce2ebfea5450', '', '', '2024-05-22 07:37:38', '2024-05-22 07:37:38', '', 0, 'http://localhost/?p=26', 0, 'customize_changeset', '', 0),
