	(85, 1, '2024-05-27 13:19:44', '2024-05-27 05:19:44', '<!-- wp:html -->\n<button class="accordion active">National Research Center</button>\n<div class="panel" style="max-height: 100vh;">\n  <ul class="show-bullet">\n     <li>Philippine Rice Research Institute (PhilRice)</li> \n     <li>Biotechnology Coalition of the Philippines (BCP)</li> \n     <li>DA - Fisheries Biotechnology Center (DA-FBC)</li> \n     <li>DA - Livestock Biotechnology Center (DA-LBC)</li>\n     <li>DA - Biotechnology Program Office (DA-BPO)</li>\n     <li>DA - Bureau of Plant Industry (DA-BPI)</li>\n  </ul>\n</div>\n<button class="accordion active">State Universities and Colleges</button>\n<div class="panel" style="max-height: 100vh;">\n  <ul class="show-bullet">\n     <li>University of the Philippines - Los Baños Laguna</li> \n     <li>Visayas State University</li> \n     <li>University of Southern Mindanao</li> \n     <li>Central Luzon State University</li> \n     <li>University of Mindanao</li> \n     <li>Caraga State University</li>\n  </ul>\n</div>\n<!-- /wp:html -->', 'Collaborators', '', 'publish', 'closed', 'closed', '', 'collaborators', '', '', '2024-05-28 15:52:32', '2024-05-28 07:52:32', '', 0, 'http://localhost/?page_id=85', 0, 'page', '', 0),
	(86, 1, '2024-05-27 13:19:44', '2024-05-27 05:19:44', '{\n    "nav_menus_created_posts": {\n        "value": [\n            85\n        ],\n        "type": "option",\n        "user_id": 1,\n        "date_modified_gmt": "2024-05-27 05:19:41"\n    },\n    "nav_menu_item[-3265144166979328000]": {\n        "value": {\n            "object_id": 85,\n            "object": "page",\n            "menu_item_parent": 0,\n            "position": 3,\n            "type": "post_type",\n            "title": "Collaborators",\n            "url": "http://localhost/?page_id=85",\n            "target": "",\n            "attr_title": "",\n            "description": "",\n            "classes": "",\n            "xfn": "",\n            "status": "publish",\n            "original_title": "Collaborators",\n            "nav_menu_term_id": 6,\n            "_invalid": false,\n            "type_label": "Page"\n        },\n        "type": "nav_menu_item",\n        "user_id": 1,\n        "date_modified_gmt": "2024-05-27 05:19:41"\n    },\n    "nav_menu_item[-7585114780905120000]": {\n        "value": {\n            "object_id": 85,\n            "object": "page",\n            "menu_item_parent": 0,\n            "position": 4,\n            "type": "post_type",\n            "title": "Collaborators",\n            "url": "http://localhost/?page_id=85",\n            "target": "",\n            "attr_title": "",\n            "description": "",\n            "classes": "",\n            "xfn": "",\n            "status": "publish",\n            "original_title": "Collaborators",\n            "nav_menu_term_id": 6,\n            "_invalid": false,\n            "type_label": "Page"\n        },\n        "type": "nav_menu_item",\n        "user_id": 1,\n        "date_modified_gmt": "2024-05-27 05:19:41"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', 'b2c22942-9a69-4f45-8d21-ae4536dd8c05', '', '', '2024-05-27 13:19:44', '2024-05-27 05:19:44', '', 0, 'http://localhost/?p=86', 0, 'customize_changeset', '', 0),
